#include "ark/sketch.hpp"
#include <cmath>
#include <algorithm>
#include <functional>
#include <stdexcept>
namespace ark {
arkjson::Value sampleEquationCurve(const arkjson::Value& spec,const ExprEnv& env){
    using V=arkjson::Value;if(spec.t!=V::Obj)throw std::runtime_error("XYZ equation curve requires an object");
    for(const auto& field:spec.obj)if(field.first!="op"&&field.first!="x"&&field.first!="y"&&field.first!="z"&&field.first!="t0"&&field.first!="t1"&&field.first!="samples"&&field.first!="tolerance"&&field.first!="analytic")throw std::runtime_error("Unknown equation field: "+field.first);
    // Name the missing field and the whole contract: an agent cannot recover
    // from "needs ... samples" when it does not know samples is a field.
    static const std::string contract=" XYZ equation curve: native:{op:equation,x,y,z (expressions of t and parameters),t0,t1,samples:integer 2..512 interpolation stations,tolerance?:mm adaptive refinement}; exact analytic form: native:{op:equation,analytic:{kind:polynomial|circle|ellipse,...},t0,t1}.";
    auto evaluate=[&](const char* key,const ExprEnv& local){const auto* value=spec.find(key);if(!value)throw std::runtime_error(std::string("Equation curve is missing native.")+key+"."+contract);if((value->t!=V::Str&&value->t!=V::Num)||value->str.size()>2048)throw std::runtime_error(std::string("Equation native.")+key+" must be a number or an expression string."+contract);bool ok=false;const double result=value->t==V::Num?value->num:evalExpr(value->str,local,&ok);if(value->t==V::Num)ok=true;if(!ok||!std::isfinite(result)||std::abs(result)>1e7){std::string at;if(const auto t=local.vars.find("t");t!=local.vars.end())at=" at t="+std::to_string(t->second);throw std::runtime_error(std::string("Equation native.")+key+" does not evaluate to a finite value"+at+(value->t==V::Str?": "+value->str:std::string())+". Use t, pi and existing parameter names.");}return result;};
    if(const V* analytic=spec.find("analytic")){
        if(spec.find("x")||spec.find("y")||spec.find("z"))throw std::runtime_error("Equation chooses analytic source or XYZ expressions");if(analytic->t!=V::Obj||!analytic->find("kind")||analytic->find("kind")->t!=V::Str)throw std::runtime_error("Analytic equation needs a typed object");const std::string kind=analytic->find("kind")->str;const double t0=evaluate("t0",env),t1=evaluate("t1",env);if(t1<=t0)throw std::runtime_error("Analytic equation t1 must exceed t0");
        auto scalarValue=[&](const V& item){bool ok=item.t==V::Num;double x=ok?item.num:item.t==V::Str?evalExpr(item.str,env,&ok):0;if(!ok||!std::isfinite(x)||std::abs(x)>1e7)throw std::runtime_error("Invalid analytic equation input");return x;};V request=V::makeObj();request.set("op",V::makeStr("curve_analytic"));request.set("kind",V::makeStr(kind));request.set("t0",V::makeNum(t0));request.set("t1",V::makeNum(t1));
        if(kind=="polynomial"){
            for(auto& field:analytic->obj)if(field.first!="kind"&&field.first!="x"&&field.first!="y"&&field.first!="z")throw std::runtime_error("Unknown polynomial equation field");std::vector<std::vector<double>> coefficients;size_t degree=0;for(const char* axis:{"x","y","z"}){const V* list=analytic->find(axis);if(!list||list->t!=V::Arr||list->arr.empty()||list->arr.size()>26)throw std::runtime_error("Polynomial axes require 1..26 ascending power coefficients");std::vector<double> values;for(auto& coefficient:list->arr)values.push_back(scalarValue(coefficient));degree=std::max(degree,values.size()-1);coefficients.push_back(values);}if(!degree)throw std::runtime_error("Polynomial curve is a constant point");auto choose=[](unsigned n,unsigned k){double c=1;for(unsigned i=1;i<=k;++i)c=c*(n-k+i)/i;return c;};std::vector<std::vector<double>> powers(3,std::vector<double>(degree+1));for(unsigned axis=0;axis<3;++axis)for(unsigned k=0;k<=degree;++k)for(unsigned i=k;i<coefficients[axis].size();++i)powers[axis][k]+=coefficients[axis][i]*choose(i,k)*std::pow(t0,(int)(i-k))*std::pow(t1-t0,(int)k);V poles=V::makeArr();for(unsigned j=0;j<=degree;++j){V point=V::makeArr();for(unsigned axis=0;axis<3;++axis){double coordinate=0;for(unsigned k=0;k<=j;++k)coordinate+=powers[axis][k]*choose(j,k)/choose((unsigned)degree,k);if(!std::isfinite(coordinate)||std::abs(coordinate)>1e7)throw std::runtime_error("Polynomial Bernstein controls exceed finite domain");point.arr.push_back(V::makeNum(coordinate));}poles.arr.push_back(point);}request.set("poles",poles);
        }else if(kind=="circle"||kind=="ellipse"){
            for(auto& field:analytic->obj)if(field.first!="kind"&&field.first!="center"&&field.first!="normal"&&field.first!="x_axis"&&field.first!=(kind=="circle"?"radius":"major")&&(kind=="circle"||field.first!="minor"))throw std::runtime_error("Unknown analytic circle/ellipse field");for(const char* key:{"center","normal","x_axis"}){const V* vector=analytic->find(key);if(!vector||vector->t!=V::Arr||vector->arr.size()!=3)throw std::runtime_error("Analytic curve center/axes require XYZ");V result=V::makeArr();for(auto& coordinate:vector->arr)result.arr.push_back(V::makeNum(scalarValue(coordinate)));request.set(key,result);}for(const char* key:kind=="circle"?std::vector<const char*>{"radius"}:std::vector<const char*>{"major","minor"}){const V* field=analytic->find(key);if(!field)throw std::runtime_error("Missing analytic radius");request.set(key,V::makeNum(scalarValue(*field)));}if(t1-t0>K_2PI+1e-10)throw std::runtime_error("Analytic circle/ellipse supports at most one full turn");
        }else throw std::runtime_error("Analytic equation kind must be polynomial, circle or ellipse");return request;
    }
    const double t0=evaluate("t0",env),t1=evaluate("t1",env),samples=evaluate("samples",env);if(t1<=t0||samples<2||samples>512||samples!=std::floor(samples))throw std::runtime_error("Equation needs t1 > t0 and 2..512 interpolation samples");
    V points=V::makeArr();Vec3 prior;for(unsigned i=0;i<(unsigned)samples;++i){ExprEnv local=env;local.vars["t"]=t0+(t1-t0)*i/(samples-1);Vec3 p{evaluate("x",local),evaluate("y",local),evaluate("z",local)};if(i&&(p-prior).len()<1e-8)throw std::runtime_error("Equation has coincident consecutive samples");prior=p;V point=V::makeArr();for(double value:{p.x,p.y,p.z})point.arr.push_back(V::makeNum(value));points.arr.push_back(point);}
    const double tolerance=spec.find("tolerance")?evaluate("tolerance",env):.01;if(tolerance<1e-6||tolerance>5)throw std::runtime_error("Equation observed tolerance must be 1e-6..5 mm");
    V parameters=V::makeArr();for(unsigned i=0;i<(unsigned)samples;++i)parameters.arr.push_back(V::makeNum(t0+(t1-t0)*i/(samples-1)));
    V source=V::makeObj(),variables=V::makeObj();for(const char* key:{"x","y","z"})source.set(key,*spec.find(key));for(const auto& item:env.vars)variables.set(item.first,V::makeNum(item.second));source.set("variables",variables);source.set("tolerance",V::makeNum(tolerance));source.set("authored_samples",V::makeNum(samples));
    V evidence=V::makeObj();evidence.set("authored_samples",V::makeNum(samples));evidence.set("equation_between_samples_bound_verified",V::makeBool(false));evidence.set("requested_observed_tolerance_mm",V::makeNum(tolerance));
    // Planar recipes use an explicit adaptive polyline. Chord deviation is
    // measured at seven stations per interval; arbitrary equations can have
    // features between those stations, so this is evidence, not a global bound.
    if(spec.find("tolerance")){
        auto at=[&](double t){ExprEnv local=env;local.vars["t"]=t;return Vec3{evaluate("x",local),evaluate("y",local),evaluate("z",local)};};V refined=V::makeArr(),refinedParameters=V::makeArr();unsigned evaluations=0;double observed=0;
        auto append=[&](double t,Vec3 p){if(refined.arr.size()>=4096)throw std::runtime_error("Equation adaptive sampling exceeds 4096 points; split the domain");V point=V::makeArr();for(double x:{p.x,p.y,p.z})point.arr.push_back(V::makeNum(x));refined.arr.push_back(point);refinedParameters.arr.push_back(V::makeNum(t));};
        std::function<void(double,Vec3,double,Vec3,unsigned)> refine=[&](double a,Vec3 pa,double b,Vec3 pb,unsigned depth){double error=0;for(unsigned j=1;j<8;++j){double f=j/8.;Vec3 real=at(a+(b-a)*f);++evaluations;error=std::max(error,(real-(pa+(pb-pa)*f)).len());}if(error>tolerance){if(depth>=20)throw std::runtime_error("Equation refinement did not meet observed tolerance");double middle=(a+b)*.5;Vec3 pm=at(middle);refine(a,pa,middle,pm,depth+1);refine(middle,pm,b,pb,depth+1);}else{observed=std::max(observed,error);append(b,pb);}};
        append(t0,at(t0));for(unsigned i=1;i<(unsigned)samples;++i){double a=t0+(t1-t0)*(i-1)/(samples-1),b=t0+(t1-t0)*i/(samples-1);refine(a,at(a),b,at(b),0);}points=refined;parameters=refinedParameters;evidence.set("resolved_samples",V::makeNum(points.arr.size()));evidence.set("checkpoint_evaluations",V::makeNum(evaluations));evidence.set("observed_max_chord_error_mm",V::makeNum(observed));
    }
    V request=V::makeObj();request.set("op",V::makeStr("curve_interpolate"));request.set("points",points);request.set("parameters",parameters);request.set("equation_source",source);request.set("equation_evidence",evidence);return request;
}
}
